                        let mut best_pos: IdxSize = start_pos as IdxSize;

                        for (pos, &i) in idx.iter().enumerate().skip(start_pos + 1) {
                            if let Some(v) = unsafe { arr.get_unchecked(i as usize) } {
                                if v.nan_max_lt(&best_val) {
